const e={langName:"简体中文"},t={appTitle:"SECTOR-07",appSubtitle:"撤离倒计时",appTagline:"7 号闸门",day:"第 {day} 天 / 共 {max} 天",stat:{health:"健康",sanity:"理智",money:"信用点",favor:"人脉"},ap:{label:"今日剩余行动点",upkeep:"配给 {n}/日 · 每 {every} 天涨价"},goal:{money:"撤离船票需 {money} 信用点",favor:"或人脉 ≥ {favor}",secured:"船票已锁定"},act:{gate:"第一幕 · 闸门",fault:"第二幕 · 断层",list:"第三幕 · 名单"},action:{endDay:"结束今日执勤，返回宿舍",confirm:"确认并继续",hold:"按住",restart:"重新开始值班",start:"开始执勤",share:"生成分享图",continue:"继续上次",newGame:"重新开始",close:"关闭"},story:{premise:"灰烬症越过第三道封锁线已经第九十天。你是 7 号闸门的检疫员，手里一枚章，决定谁能过去。最后一班撤离潜艇在十八天后离港，四百个座位，闸门外有六万人。",switch:"切换剧本",pickerTag:"剧本库",title:"选择要进入的世界",current:"当前",saved:"第 {day} / {max} 天有存档",hint:"每个剧本都是独立的世界，存档、结局档案互不影响。",close:"关闭"},badge:{chain:"因果连锁",new:"新线索",key:"关键",chainPending:"待续",chainFrom:"起于第 {day} 天"},roll:{tag:"赌一把",win:"得手",lose:"失手",likely:"多半能成",even:"五五之数",thin:"三分胜算",grim:"凶多吉少"},dayCard:{day:"第 {day} 天",income:"执勤 +{n}",spend:"配给 -{n}",hint:"轻触继续",off:"不再显示过场"},interlude:{fault:"第七天。闸门外的队伍没有变短，地图上的红线开始往里挪。",list:"第十三天。名单已经写好了，只差你在最后一栏落笔。"},event:{tag:"事件",locked:"锁定",apCost:"-{n} AP",rollWin:"赌赢了",rollLose:"赌输了"},log:{title:"行动日志",boot:"终端已连接。灰烬症正在蔓延，请谨慎做出每一次盖章决定。",dayStart:"第 {day} 天值班开始，行动点恢复至 {n} 点。",upkeepPaid:"宿舍日结：扣除 {n} 信用点购买净水与合成食物。",wage:"今日执勤津贴到账：+{n} 信用点。",upkeepFail:"信用点不足！严重脱水与饥饿导致健康 -25。",arrive:"抵达{loc}。",effectNone:"无数值变动",saved:"进度已自动保存。",restore:"睡了一觉，理智 +{n}。"},ending:{archive:"SECTOR-07 档案",win:"成功撤离",lose:"滞留沦陷",rarity:"结局稀有度",trajectory:"关键道德抉择",noChoice:"你在十八天里谨小慎微，没有留下任何极端抉择。",days:"存活 {n} 天",shareHint:"长按或右键保存图片，发到 TikTok / Twitter / Instagram",shareFail:"图片生成失败，请重试",sealLine1:"第七區",sealLine2:"檔案"},settings:{sound:"音效",music:"环境音",on:"开",off:"关",language:"语言"},contacts:{title:"关系档案",open:"关系",close:"返回",hint:"这四个人的结局，取决于你在十八天里怎么对待他们。",status:{unknown:"未接触",met:"已接触",ally:"同盟",betray:"决裂"}},rarity:{1:"普通",2:"少见",3:"罕见",4:"史诗",5:"传说"},share:{label:"SECTOR 07 // 撤离档案",stats:"最终体征",code:"档案编号",footer:"THE LAST GATE"}},o={rachel:{name:"瑞秋",role:"“生锈锚点”老板 / 走私网络节点",bio:"她的价目表上没有道德这一栏。你要是问她为什么还留在这儿，她会说因为这里有酒。",stage:{unknown:"你还没进过那间地下酒馆。",met:"她记得你的脸，也记得你欠她的人情。",ally:"她把你算进了自己人——那意味着货舱、钥匙，或者一句谎话。",betray:"她不会再给你第二次机会。"}},chen:{name:"陈静",role:"隔离区医疗站医生",bio:"她已经有四十七天没睡过一个整觉，还在数血清的支数。",stage:{unknown:"医疗站的门一直开着，你还没走进去。",met:"她跟你说话时手一直在整理器械，眼睛没离开过你。",ally:"她把冷藏箱的钥匙给了你一份。",betray:"她看见你会先看一眼门口。"}},ilya:{name:"伊莱",role:"黑市证件贩子",bio:"他没有左手，但能把任何人的脸装进任何一本护照。",stage:{unknown:"集市最里面那张折叠桌，你还不知道是谁的。",met:"他记住了你走路的姿势，也记住了你还欠他多少钱。",ally:"他愿意为你冒一次险，只一次。",betray:"他把你的名字写进了那本小本子。"}},nadia:{name:"娜迪亚",role:"14 岁 / 短波广播员",bio:"她在通风管里念名单，声音很轻，四百公里外有人听得见。",stage:{unknown:"上铺的通风口，你从没打开过。",met:"她知道你叫什么，也知道你住在哪一床。",ally:"她把最后一张自己画的登船证留给了你。",betray:"她再也不会在这个频率上出现了。"}}},c={gate:{name:"7 号闸门执勤亭",desc:"审查通行证、领取薪水，或在暗处收下信封。"},pub:{name:"“生锈锚点”地下酒馆",desc:"与走私头目瑞秋交易，打探黑市船票的门路。"},medbay:{name:"隔离区医疗站",desc:"注射血清或镇定剂，维持生存体征。"},market:{name:"黑市集市",desc:"假证、器官、骰子，什么都收，什么都卖。"},dorm:{name:"执勤宿舍",desc:"睡一会儿、听听电台，或者面对镜子里的自己。"}},i={dorm_nadia_intro:{title:"通风管里有光",desc:"凌晨两点，上铺的通风口透出一线蓝光，还有很轻的说话声。你撬开格栅，看见一个十四岁的女孩，抱着一台改装过的短波电台，正在念一份名单。",choices:{feed:{text:"给她吃的，让她留下",req:"需 5 信用点",outcome:"你塞给她两块压缩饼干和一罐豆子。她吃得很快，然后说：“我叫娜迪亚。我在把名单念出去，外面有人在听。”"},evict:{text:"让她走",outcome:"你说这里不能住人。她收好电台，动作很熟练，像是搬过很多次。走之前她说：“你也会需要有人替你说话的。”"},report:{text:"报告宿管",outcome:"三十五信用点。宿管带了两个人上来，把通风管拆了。女孩被带走时一直在看你的脸，好像要把你记住。"}}},dorm_nadia_parts:{title:"发射机缺一个电容",desc:"娜迪亚把电台后盖打开给你看，里面有一半是手工焊的。“功率不够，只能覆盖四十公里。”她说，“医疗站有配件，但那里有人守。”",choices:{steal_parts:{text:"去医疗站偷",outcome:"你从维修间拿了三个电容和一卷铜线。出来时撞见夜班护士，她看了你一眼，什么也没说。"},buy_parts:{text:"花钱买",req:"需 40 信用点",outcome:"四十信用点，从黑市买了一套完整的功放模块。装上以后，电台的指示灯第一次亮成了绿色。"},give_up:{text:"算了",outcome:"你说这不值得。她点点头，把后盖装回去。“没关系，”她说，“我念小声一点。”"}}},dorm_nadia_broadcast:{title:"今晚她要念完全部名单",desc:"娜迪亚把四百个名字抄在练习本上，字很小。“念完要四个小时。”她说，“全城的短波都能收到。他们会来抓我。”她抬起头，“你要不要拦我？”",choices:{let_her:{text:"让她播",req:"需理智 ≥ 40",outcome:"她念到第三个小时嗓子就哑了。你替她念完了最后一百二十个名字。第二天全城都在传那份名单，第三天宪兵开始挨家挨户搜收音机。"},stop_her:{text:"拦住她",outcome:"你拔掉了电源。她没有哭，只是把练习本合上，说：“我明天再念。”你把电源线藏了起来，她没有找。"},do_it_yourself:{text:"你自己来念",outcome:"你把她推出门外，自己坐在电台前。你的声音在电波里听起来很陌生。念到第七十个名字时，你听见楼下有车停下了。"}}},dorm_nadia_raid:{title:"搜查队上了楼",desc:"凌晨四点，走廊里全是靴子声。娜迪亚的电台还热着。你有大概四十秒。",choices:{hide_her:{text:"把她塞进值勤柜",outcome:"柜子只有六十公分宽，她蜷在里面抱着电台。搜查队在你床边站了六分钟。他们走后，她在柜子里又待了半个小时才敢出来。"},hand_over:{text:"把她交出去",outcome:"六十信用点。她被带走的时候没有挣扎，只问了一句：“是你吗？”你没有回答。这可能是你这辈子最安静的一次沉默。"},roof_escape:{text:"让她从屋顶走",outcome:"你把床单拧成绳，把她从三楼放下去。她落地时崴了脚，但跑得很快。电台留在了你的床底下。"}}},dorm_nadia_choice:{title:"她没有票",desc:"娜迪亚把电台拆成零件，装进一个帆布包。“我不走。”她说，“我在这儿还有用。”她十四岁，没有登船证，也没有人会替她签一张。",choices:{give_ticket:{text:"把自己的票给她",outcome:"你把票塞进她帆布包最里面。她掏出来看了很久，说：“那你怎么办？”你说你有别的办法。你其实没有。"},let_stay:{text:"让她留下",outcome:"你帮她把天线重新架到屋顶。她调好频率，念了一句“7 号闸门，测试”，然后笑了。你那天没有劝她。"},tell_truth:{text:"告诉她你也没票",outcome:"她愣了一下，然后从包里掏出一张纸，是她自己画的登船证。“我画了很多张，”她说，“你要一张吗？”"}}},dorm_guard_search:{title:"防暴队来查违禁品",desc:"六个人，两分钟一间房。你的床板下面有东西——枪、封条，或者一台不该存在的电台。",choices:{comply:{text:"配合，交罚款",req:"需 15 信用点",outcome:"十五块，算“违规持有管制物品”。他们把东西装进袋子，临走时其中一个拍了拍你的肩，说“老实点”。"},hide_stuff:{text:"把东西塞进天花板",outcome:"你踩着上铺把东西全推上去。他们翻了床、翻了柜子，没有抬头。走的时候其中一个人说：“这屋里味道不对。”"},point_next_door:{text:"指向隔壁",outcome:"二十信用点，隔壁被抄了。那间房住着三个人，其中一个第二天搬走了，走之前在你门口站了很久。"}}},dorm_letter_reply:{title:"母亲回信了",desc:"信封上的字很抖，邮戳是两个月前的。你把它放在桌上，看了十分钟才拆。",choices:{read_reply:{text:"拆开读",outcome:"她说家里的井干了，说他很好，说不用回来。最后一行写着：“你爸把你的房间一直留着。”你把信读了三遍。"},no_reply:{text:"不拆，收进箱底",outcome:"你把信压在一堆旧制服下面。它在那里放了很久，你每天都知道它在。"}}},dorm_rooftop:{title:"屋顶上能看见潜艇",desc:"凌晨，潜艇在远处试航，尾灯在水面上拖出一条红线。它比你想的小很多。",choices:{count_berths:{text:"数它的舱位",outcome:"你数了三遍，四百二十个。名单上是四百个名字，闸门外有六万人。你把这个数字记在心里，没有告诉任何人。"},just_watch:{text:"只是看",outcome:"你在屋顶坐到天亮，风很冷。潜艇回去的时候没有再开灯。你下楼时觉得心里空了一块，但也轻了一块。"},with_nadia:{text:"带娜迪亚一起看",req:"需见过娜迪亚",outcome:"她第一次看见潜艇，看了很久，然后说：“它好小。”你说是啊。她说：“那我们就得让更多人留下来。”"}}},gate_queues:{title:"队伍排到了三公里外",desc:"编号系统在第四天崩溃了。三万人在雨里站着，手里攥着过期的号牌。有人开始用孩子的名字换一个靠前的位置。防暴队的探照灯每四十秒扫过一次队伍。",choices:{triage:{text:"作废号牌，按年龄重排——老人和孩子先过",outcome:"你把号牌全部作废，按年龄重排。队伍安静了十分钟，然后一个男人把儿子举过肩头，说他才三岁。那孩子已经十二岁了。"},auction:{text:"把前排的位置卖给付得起钱的人",outcome:"第一个位置卖了三十五信用点。卖到第七个时，后面的人开始往前挤，你听见骨头被压断的声音，但那天你没有抬头。"},shut:{text:"关上窗口，等防暴队来处理",outcome:"你落下卷帘门，在门后坐了两个小时。防暴队用了四十分钟清场。第二天有人在闸门外的墙上写了一个名字，是你的。"}}},gate_deserter_return:{title:"他回来了，带着一张地图",desc:"你放走的那个逃兵站在窗口外，瘦了十斤，怀里揣着一张手绘地图。“第三补给站的血清车每晚十一点经过 B 区，两辆，只有四个人押车。”他把地图从缝隙塞进来，“我不是来要东西的。”",choices:{believe:{text:"相信他，把地图收下",outcome:"地图上标着一条巡逻盲区，笔迹很抖。你后来才知道，他为了画这条线，在雨里趴了三个晚上。"},doubt:{text:"当这是陷阱，把他赶走",outcome:"他把地图收回去，折成很小的一块塞进鞋里。“我明白了。”他说。他没有再解释。"},sell_him:{text:"记住他出现的位置，换赏金",outcome:"赏金四十五信用点，比上次高。执行队带走了他，这次没有让他再跑。你收钱的时候，指头在屏幕上按错了两次。"}}},gate_guard_grudge:{title:"他们记得是你叫的防暴队",desc:"三个防暴队员站在窗口，头盔夹在腋下。领头的那个脸上有一道新抓痕。“那天晚上我们抬走了四个人，其中一个是我弟弟。”他说得很平静，“你现在方便出来一下吗？”",choices:{drinks:{text:"请他们喝一杯，把话说开",req:"需 15 信用点",outcome:"三杯劣质酒花了十五块。他们没再提弟弟，只是走的时候，其中一个把杯子倒扣在桌上——在这儿，那意思是“这事没完”。"},stand:{text:"硬顶，告诉他们你只是在执行命令",outcome:"第一拳打在胸口，第三下你就记不清了。你在地上躺了很久，起来时制服扣子掉了两颗。"},remember:{text:"把他们的编号记下来，什么都不说",outcome:"你把三个编号抄在值班本背面，抄得很慢。他们走后，你在灯下看了那串数字很久。"}}},gate_audit_return:{title:"监察员带着封条回来了",desc:"上次那个人站在窗口，手里拿着一卷红色封条。“你上次给我的东西，我上交了。”他把封条在手指间绕了一圈，“现在轮到我问你——你想让我封哪一边？”",choices:{ledger:{text:"交出账本，让他封",req:"需 30 信用点（罚金）",outcome:"你交了三十块罚金，账本被订上第三十七页。他走的时候说：“你还算识相。”"},counter:{text:"反手举报他收了你的钱",req:"需理智 ≥ 50",outcome:"你把日期、金额、他收钱时的表情全写在举报单上。两天后他被带走了。有人在食堂说，举报的人真狠。"},pay_again:{text:"再塞一次钱",req:"需 60 信用点",outcome:"他数了两遍，然后笑着把封条收进口袋。这一次他记得问你要收据。"}}},gate_rifle:{title:"那支枪还在床底下",desc:"逃兵留下的步枪还在你的床板下，用雨衣裹着。今天集市上有人出价五十。它也意味着，如果搜查队来了，你解释不清。",choices:{sell:{text:"卖掉",outcome:"五十五信用点，买主没有问来路。你把枪递过去的时候，手指在扳机护圈上停了一下。"},keep:{text:"留着防身",outcome:"你重新给它上了油，塞回床板下。那天晚上你睡得很浅，但比之前踏实。"},hand_in:{text:"上交给检疫处",outcome:"值班长看了你三秒，在登记表上写“主动上交”，给你记了一次嘉奖。你走出办公室时，听见背后有人说“这人有点意思”。"}}},gate_lockdown_blame:{title:"追责：那扇门是谁开的",desc:"隔离营清空后的第四天，调查组进驻。他们调出了那晚的监控——只调到了闸门开启的十一秒。十一个人在那十一秒里跑了出去。",choices:{confess:{text:"承认是你开的门",outcome:"你被停职十四天，扣掉全部绩效，但没有被移交。调查组的人合上本子时说：“你至少没有撒谎。”"},frame:{text:"推给当晚已经死了的值班员",outcome:"死人不会申辩。你把时间对得很准。结案那天，你在食堂看见他女儿在打饭，她没有认出你。"},hide:{text:"消失几天，让他们找不到人",outcome:"你在 C 区的下水道里躲了三天，靠一包压缩饼干活着。回来那天没人问你去了哪，但你的名字从值班表上消失了。"}}},gate_tunnel:{title:"排水隧道里有人",desc:"巡夜时你听见闸门下方有回声——不是水声，是铁锹。C 区的人在挖一条穿过封锁线的排水隧道，已经挖了四十米。他们看见你，没有人停手。",choices:{dig:{text:"下去帮他们挖",outcome:"你在泥水里干了四个小时，指甲断了两根。他们递给你一壶水，没有人说谢谢，也没有人问你为什么。"},report:{text:"上报，封掉隧道",outcome:"工程队第二天灌了水泥。四十米，用了三车。赏金四十信用点，你在收据上签字时手很稳。"},ignore:{text:"装作没听见",outcome:"你把手电照向另一个方向，走完了剩下的巡逻路线。隧道后来通了。你从没走过，但你知道它在。"}}},gate_press:{title:"宣传队来了",desc:"两个穿冲锋衣的人架起摄像机，要拍“有序撤离”。他们让你站在窗口，手里拿章，笑一下。“就拍十秒，全联邦都会看到 7 号闸门的高效。”",choices:{perform:{text:"配合拍摄",outcome:"他们拍了十七条，选了第三条。你笑得像个刚拿到退休金的人。第二天你收到二十五信用点的“协助宣传”补贴。"},turn_camera:{text:"把镜头转向排队的人",outcome:"摄像师愣了一下，然后真的转过去了。三千张脸在镜头里，没有一个人笑。这段素材后来没有播出来。"},grab:{text:"抢下摄像机",outcome:"你把机器砸在闸门上，碎片划破了手。宣传队当天撤走了。你被记了一次“情绪失控”，那年没评上先进。"}}},gate_evac_list:{title:"撤离名单只有四百行",desc:"名单存在值班终端里，四百个名字，加密的。潜艇额定载客四百。闸门外有六万人。名单第三行是你自己的名字——有人已经替你签好了。",choices:{copy:{text:"复制一份，带走",outcome:"你用三分钟拷完了它。屏幕上跳出一行提示：“此操作已被记录。”你没有停。"},sell_copy:{text:"把名单卖给黑市",outcome:"九十信用点，买家没有还价。三天后四十个不在名单上的人拿到了登船证。剩下三百六十个位置，空着。"},burn:{text:"删掉名单",outcome:"你按了三次确认，屏幕黑了。四百个位置从此变成先到先得。你不知道这是救了他们还是害了他们。"}}},gate_list_use:{title:"那份名单现在在你手上",desc:"名单在你口袋里，纸边已经被汗浸软。闸门外的人还在等，潜艇后天凌晨到。你有权限，也有一份名单。",choices:{by_list:{text:"只放名单上的人",outcome:"你念了四百个名字，念了六个小时。念到第一百七十个时嗓子哑了。名单外的人开始撞门，你继续念。"},give_rachel:{text:"把名单交给瑞秋",outcome:"她接过纸，看了很久，然后说：“你知道这东西能卖多少钱吗？”你说知道。她把名单折好，放进内衣口袋。"},tear:{text:"撕掉",outcome:"你把纸撕成四片，扔进焚化炉。四百个名字烧了不到三秒。你站在那儿，直到炉子冷下来。"}}},gate_last_night:{title:"最后一夜",desc:"潜艇凌晨四点离港。闸门外的探照灯坏了两盏，黑暗里有几千人在等。值班表上今晚只有你一个人。",choices:{hold:{text:"守住闸门，按规程做完最后一班",outcome:"你守到四点，一页一页写完交接记录。潜艇离港时没有鸣笛。你在“异常情况”一栏写了两个字：无。"},clock_out:{text:"提前走，去码头",outcome:"你关了岗亭的灯，钥匙留在锁孔里。走到半路回头看了一眼，闸门在雨里黑着，像一张闭上的嘴。"},open:{text:"打开闸门，让他们全过去",req:"需理智 ≥ 40",outcome:"你按下绿色按钮，然后关掉了监控。人群涌进来的时候没有欢呼，只有脚步声，像一场下了很久的雨终于落到地上。"}}},gate_tunnel_escape:{title:"隧道通了",desc:"C 区的人在凌晨来找你，身上全是泥。“通了，一直通到封锁线外的旧泵站。”领头的那个看着你，“要不要一起走？还有十四个位置。”",choices:{alone:{text:"一个人走",outcome:"你在黑暗里爬了四十分钟，出来时天刚亮。身后没有脚步声。你活了，这件事后来你想了很久。"},lead_them:{text:"带他们一起走",req:"需瑞秋 ≥ 30",outcome:"十六个人，两个孩子，一个孕妇。爬到最后十米时手电灭了，你摸着墙把所有人一个一个推出去。清点时少了一个，谁也没敢回头找。"},collapse:{text:"炸掉隧道",outcome:"你点燃引信，退到三十米外。塌方声很闷，像有人在地底叹了一口气。第二天你在值班记录里写：“发现结构隐患，已排除。”"}}},gate_overtime:{title:"连班",desc:"值班表上多出一个空位——有人请了病假。值班长问你要不要接，双倍津贴，但要连着站十六个小时。闸门外的队伍不会因为你不舒服就散去。",choices:{double:{text:"接。双倍津贴",outcome:"十六个小时，你盖了四百多张章，中间只去过一次厕所。下班时津贴到账，数字很好看。回到宿舍，脱鞋脱了三次才脱下来。"},normal:{text:"不接，按时下班",outcome:"你说不接。值班长耸耸肩，把表填上了别人的名字。你按时下班，路上买了一碗热汤。"}}},market_ilya_intro:{title:"缺了左手的证件贩子",desc:"他坐在一张折叠桌后面，左手的位置空着，袖子掖进腰带。“你要什么身份？”他把三本护照摊开，“工人、护士，还有一本检疫处的——这本贵，但没人敢查你。”",choices:{buy_papers:{text:"买一本新身份",req:"需 55 信用点",outcome:"你挑了护士那本。他把照片换成你的，用一根加热的勺子压边，动作比机器还稳。“尾款到货再付，”他说，“我不怕你跑，这地方就这么大。”"},buy_pass:{text:"只买一张通行证",req:"需 20 信用点",outcome:"二十块，一张手写的通行证，章是真的。“一次性的，”他强调，“别拿去赌。”"},rob_him:{text:"抢他的抽屉",outcome:"抽屉里有四百多信用点，还有七本别人的身份。他没有反抗，只是用右手抱住空着的左袖，说：“你拿走的不是我一个人的。”"}}},market_ilya_papers:{title:"那本护照是死人的",desc:"伊莱把护照推过来。“登记的名字叫周琳，二十九岁，三天前死在隔离营。”他敲了敲照片，“现在她是你的了。尾款六十，或者你现在就可以走。”",choices:{pay_full:{text:"付清尾款",req:"需 60 信用点",outcome:"他收了钱，把护照用油纸包好塞进你怀里。“记住她的生日，”他说，“查的人有时候会问。”"},haggle:{text:"压价到三十五",req:"需 35 信用点",outcome:"他盯着你看了很久，最后说“行”。少收的二十五块他记在一个小本子上。“我不催你，”他说，“但我会记得。”"},back_out:{text:"反悔，不要了",outcome:"他把护照收回抽屉，说“你比我想的干净”。这句话听起来不像夸奖，但你没反驳。"}}},market_ilya_arrest:{title:"稽查队把他按在桌上",desc:"三个稽查队员把伊莱的脸按在折叠桌上，翻他的抽屉。“伪造证件，够判二十年。”其中一个回头看你，“你认识他？”伊莱没有抬头。",choices:{vouch:{text:"作证说他只是修表的",req:"需瑞秋 ≥ 15",outcome:"你报了瑞秋的名字，稽查队的人对视了一眼，把人放了。伊莱站起来揉了揉脸，说：“我欠你一次。”"},silence:{text:"什么都不说",outcome:"你站在那儿，看他们把抽屉里的东西一样一样装进证物袋。伊莱被带走时用右手对你做了一个很轻的手势，像在道别。"},identify:{text:"指认他",outcome:"五十信用点，当场结清。他们给他上手铐时，他终于抬头看了你一眼。那眼神你后来在很多人脸上见过。"}}},market_ilya_debt:{title:"他欠药厂四百五",desc:"伊莱的摊子被砸了，人坐在碎玻璃中间。“药厂的钱，四百五。”他把那本小本子递给你看，上面记着每一笔，“他们给我三天。”",choices:{pay_debt:{text:"帮他还",req:"需 45 信用点",outcome:"你把钱塞进他手里。他数了两遍，然后从脖子上取下一枚铜章塞给你。“检疫处的旧章，真的。”他说，“现在它值钱了。”"},let_him:{text:"让他自己解决",outcome:"你说“我帮不了”。他点点头，把本子合上。“我懂。”三天后他的摊子没了，人还在，但左手的位置好像更空了。"},buy_stamp:{text:"买下他的印章",req:"需 25 信用点",outcome:"你把印章买了下来。他把铜章放进你手心时，手指停了一下，然后很快收回去。"}}},market_ilya_choice:{title:"最后一张真的登船证",desc:"伊莱把一张硬纸卡放在你面前，边角有压痕，是真货。“我给自己留的。”他说，“现在我给你，你带我上船。”",choices:{take_his:{text:"拿走他的证，不带他",outcome:"你把卡收进口袋。他没有拦你，只是把空着的袖子抚平，说：“你至少该说声谢谢。”"},give_to_chen:{text:"把证给陈医生",outcome:"伊莱愣了很久，然后笑了。“我这辈子做过最赚的一笔生意，”他说，“是把东西给错人。”"},burn_both:{text:"两张一起烧掉",outcome:"你当着他的面把两张证撕了，扔进炉子。他看着火，很久才说：“你知道我刚才在想什么吗？我在想，这样也挺好。”"}}},market_militia:{title:"民兵来收这个月的“保护费”",desc:"五个戴袖章的男人堵住巷口，领头的拿着一个铁皮盒子。“这个月涨了，二十。”他说，“你也可以不给，我们只是保证不了你的摊子明天还在。”",choices:{pay:{text:"交钱",req:"需 20 信用点",outcome:"你把二十块扔进铁盒。他数了数，说“爽快”，然后在你的摊子上贴了一张红色标记。"},refuse:{text:"不给",outcome:"他们打你的时候很有节奏，打完还把你扶起来。领头的说：“下个月还是二十。”你吐掉嘴里的血，说“下个月还是不给”。"},name_drop:{text:"报检疫处的名字",outcome:"你说了一个名字。他们互相看了看，收起铁盒走了。第二天你才知道，那个名字的主人是他们的上家。"}}},market_child_return:{title:"那个偷罐头的小孩回来了",desc:"他站在摊子边，比上次更瘦，手里攥着两个空罐头盒。“我能干活。”他说得很快，“搬东西、看摊、跑腿，我一天只吃一顿。”",choices:{hire:{text:"雇他",req:"需 10 信用点",outcome:"你给了他十块，让他去搬货。他搬了一天，晚上把九块半还给你，说“我只吃了一顿”。你后来再没让他饿过。"},chase:{text:"赶他走",outcome:"你挥手让他滚。他跑了三步，回头看了一眼你的摊子，那眼神不像小孩。"},ignore:{text:"当没看见",outcome:"你继续整理货，他站了大概十分钟，然后走了。两个空罐头盒留在地上，你没有捡。"}}},market_fence_seal:{title:"有人要买检疫处的封条",desc:"收赃的人开价三十五，要完整的封条，带编号，带钢印。“这东西比护照好用，”他说，“封条一贴，谁都不敢开箱。”",choices:{sell_seal:{text:"卖掉",outcome:"三十五信用点。三天后，三车“医疗物资”贴着你的封条出了城。箱子里装的是什么，你没有问。"},keep_seal:{text:"留着",outcome:"你把封条夹进值班本。它可能救你一次，也可能害死你一次。你决定等到需要它的那天。"}}},medbay_chen_intro:{title:"陈医生和三个冷藏箱",desc:"医疗站的灯只开了一半。陈医生蹲在地上数三个冷藏箱，箱子上印着药厂的批号。“血清样本，”她说，“他们明天来收走，然后烧掉。这病本来能治。”",choices:{steal_samples:{text:"帮她把箱子搬走",outcome:"你们从后门把箱子推进运尸车。她一路上没说话，到了地方才开口：“我叫陈静。你要是不来，我今晚就死在这儿。”"},buy_meds:{text:"只买药，不问别的",req:"需 20 信用点",outcome:"她收了钱，给你两盒退烧药，然后把箱子往角落里推了推。你走出门时，听见她在里面锁门。"},report_her:{text:"上报“私自藏匿样本”",outcome:"三十信用点。第二天医疗站的灯全亮了，药厂来了两辆车。陈医生被带走时，手里还拿着一支试管。"}}},medbay_chen_raid:{title:"药厂保安来了四个人",desc:"他们穿着没有标识的黑制服，手里拿着清单。“三个冷藏箱，编号 7741 到 7743。”领头的把清单拍在桌上，“陈医生，别让我们难做。”",choices:{block:{text:"挡在冷藏箱前面",outcome:"第一下打在你的肋骨上，你听见自己呼吸的声音变了。他们走的时候没拿到箱子，但把你的工牌拿走了。"},handover:{text:"让他们搬走",outcome:"箱子被搬上车，四个人动作很专业。陈医生站在走廊尽头看着，没有哭。她只是把白大褂的扣子一颗一颗扣好。"},swap:{text:"用三个假箱子换",req:"需 30 信用点",outcome:"你花三十块买了三个一样的空箱，装进冰块和生理盐水。他们搬走时称了重量，说“下次别这么慢”。"}}},medbay_chen_daughter:{title:"她女儿在 B 区",desc:"陈医生把一张照片放在桌上，边角已经磨圆了。“十四岁，在 B 区隔离营，编号 2291。”她推过来一张调令申请单，“你有签字的权限。”",choices:{pull_strings:{text:"用职权把她调出来",outcome:"你签了字，把她写成“医疗志愿者”。女孩出来那天瘦得像个影子，看见母亲时没有跑过去，只是站着。"},admit_powerless:{text:"告诉她你签不了",outcome:"她把照片收起来，说“我知道”。然后继续工作，那天做了十一台清创，一句话也没说。"},sell_hope:{text:"收钱，答应“想办法”",outcome:"二十五信用点。她每周问你一次进展，你每周说“快了”。第四周，她不再问了。"}}},medbay_trial:{title:"血清只剩十二支",desc:"冷藏箱里剩下十二支试验血清，走廊上躺着四十个重症。“按规程，这需要三期临床。”陈医生说，“按人命，现在就该打。”",choices:{run_trial:{text:"给最重的十二个人打",outcome:"九个人退烧了，三个人没有。你在记录本上写“有效率 75%”，写完发现手在抖。"},block_trial:{text:"不给，等上面的批文",outcome:"你把箱子锁进药柜。三天后批文下来了，两个人已经死了，剩下十个还在等。批文上写着“同意，但需自负风险”。"},sell_trial:{text:"卖给黑市",outcome:"六十信用点，一次交易。十二支血清当晚流进 C 区的私人诊所，一支喊价八十。你听说有人靠它活了，也听说有人靠它死了。"}}},medbay_chen_choice:{title:"这批样本只能去一个地方",desc:"陈医生把冷藏箱放在桌上，温度计指着零下十八度。“有三个买家。”她说，“检疫处、隔离营、还有你的船。你选。”",choices:{broadcast_formula:{text:"把提取配方广播出去",outcome:"你们用了三个小时把流程念完，娜迪亚的发射机把它送出四百公里。第二天，四个隔离营开始自己配药。"},trade_berth:{text:"卖给检疫处换舱位",outcome:"八十信用点，加一张手写的登船凭证。陈医生看着你收钱，然后说：“这箱子里的东西，本来能救两万人。”"},carry_aboard:{text:"带上船",outcome:"你把箱子塞进背包，重量压在肩上。它能救很多人——但前提是你能找到一间实验室。"}}},medbay_ward_round:{title:"床位不够，走廊上还躺着九个",desc:"医疗站的床位是四十张，现在躺了四十九个人。走廊上那九个是用担架抬来的，其中一个还在说话，其余八个没有声音。",choices:{unplug:{text:"拔掉最里面那张床的管",outcome:"你动作很快，没有惊动任何人。床位空出来了，护士在两分钟内铺好新的床单。你站在走廊尽头抽了半支烟。"},share_ration:{text:"把自己的配给分给病人",outcome:"你把三天的压缩饼干全给了走廊上的人。他们分着吃了，还留了半块给你。你那天饿得手抖，但睡得很好。"},walk:{text:"走一圈，什么都不做",outcome:"你走完了四十张床，记住了每一张脸。走出医疗站时，你的手在口袋里攥成了拳。"}}},medbay_quarantine_break:{title:"隔离营的墙塌了",desc:"凌晨三点，B 区隔离营的围墙被推倒。两百多个还没死的人往里涌。医疗站的门是唯一还锁着的一道。",choices:{open_ward:{text:"开门，全部收下",outcome:"你们收了六十七个人，剩下的被防暴队堵在路口。那天医疗站的地上没有一块干净的地方。"},lock:{text:"锁死，不放进来",outcome:"门外的撞击持续了四十分钟。你靠在门内侧坐着，听着，数着自己的心跳。后来外面安静了。"},ticket_only:{text:"只放有登船凭证的人",outcome:"十七个人凭纸进来了，剩下的被挡在外面。你收了三张凭证的“过路费”，一共三十信用点。那张纸在你手里发烫。"}}},medbay_stay_with_chen:{title:"她说她不走",desc:"撤离前两夜，陈医生在整理病历。“潜艇上没有实验室。”她说，“这里有两千个病人。我走了，他们连记录都没有人写。”",choices:{stay:{text:"留下陪她",outcome:"你把船票折好，塞进抽屉。她抬头看了你一眼，说“想清楚”。你说想清楚了。那天晚上你们整理了三百份病历。"},persuade:{text:"劝她上船",outcome:"你说了四十分钟，她一句没反驳，也没有答应。最后她说：“你先走，我把这批病人处理完。”你知道她不会来。"},leave_alone:{text:"一个人走",outcome:"你什么也没说，把门轻轻带上。走廊里很安静，你听见她在里面翻纸的声音，一直响到你走出大楼。"}}},pub_rachel_trust:{title:"她带你去看货舱",desc:"瑞秋掀开吧台下的地板，露出一段向下的铁梯。“潜艇的货舱，我租了两个位置。”她把手电递给你，“下面很挤，但能活。你现在知道我为什么不怕检疫处了。”",choices:{ally:{text:"跟她结盟",outcome:"你们在铁梯上握了手，她的手心有一层茧。“我不需要朋友，”她说，“但我需要一个不会在最后一刻跑掉的人。”"},business:{text:"只谈生意",outcome:"你问她位置多少钱。她报了价，你砍了十个，成交。她没有再提带你看货舱这件事。"},sell_berth:{text:"把货舱位置卖给检疫处",outcome:"六十信用点，一次付清。三天后检疫处抄了那间酒吧。瑞秋不在里面。她再也没出现在这个区。"}}},pub_rachel_crew:{title:"四个人，两个位置",desc:"瑞秋的四个船员站在吧台后面，没有人说话。她只买到两个舱位。“你替我选。”她把名单推过来，“选完，这四个人里会有两个恨你一辈子。”",choices:{draw_lots:{text:"让他们抽签",outcome:"四个人抽了签。抽到短签的那个笑了笑，说“我本来也跑不动了”。他留了下来，在闸门那边帮忙搬东西，直到最后一晚。"},pick_strong:{text:"挑最能干的两个",outcome:"你挑了肌肉最厚的两个。落选的两个人没有闹，只是当晚就搬出了酒吧。其中一个后来在集市上卖了你的行踪。"},take_one:{text:"自己占一个",outcome:"你把自己的名字写在第二个位置上。瑞秋看了你很久，什么也没说，把名单收了起来。那晚她没再和你说过一句话。"}}},pub_rachel_offer:{title:"她需要一张值班表",desc:"瑞秋把一张空白纸推过来。“潜艇靠港的时间，闸门换岗的空档，巡逻的盲区。”她敲了敲纸，“你给我这些，货舱的位置就是你的，不要钱。”",choices:{accept:{text:"答应她",outcome:"你抄了三个月的排班，抄到凌晨。她看完折成小方块塞进烟盒。从那天起，你每次听见对讲机响都会心跳加快。"},refuse:{text:"拒绝",outcome:"你把纸推回去。她挑了挑眉，说“行，那按原价”。你走出酒吧时，觉得口袋里的钱突然重了一点。"},report_her:{text:"拿着这张纸去举报她",outcome:"七十信用点，外加一次“重大立功”记录。执行队冲进酒吧时，她已经把烟盒烧了。她只说了一句：“原来是你。”"}}},pub_rachel_arrest:{title:"她被押进了岗亭",desc:"两个宪兵把瑞秋按在窗口的铁台上。她的嘴角破了，但看见你的时候笑了一下。“这个人我认识。”宪兵说，“你认识吗？”",choices:{release:{text:"放她走",req:"需瑞秋 ≥ 30",outcome:"你在交接单上签了字，说手续有误。宪兵骂了一句，还是带人走了。瑞秋从后门离开时，把一枚铜钥匙放在窗台上。"},pretend:{text:"装作不认识",outcome:"你说“没见过”。她被带走的时候一直在看你，没有喊，也没有求。三天后，酒吧换了老板。"},cuff:{text:"亲手给她上手铐",outcome:"铐子扣上时很响。她低声说：“你会有位置的。”六十信用点当天到账，备注是“协助缉私”。"}}},pub_smuggle_run:{title:"机械师那条船今晚走",desc:"那个被你救过的机械师修好了一艘漏水的拖船，只够坐八个人。“潮水两点最高，”他说，“过了就搁浅在泥里，等死。”",choices:{give_seat:{text:"把位置让给瑞秋的船员",outcome:"八个人上了船，没有你。拖船开出去两百米就熄了火，他们用手划了四个小时。天亮时船到了对岸。"},keep_route:{text:"自己留着当后路",outcome:"你记下了潮汐时间、船的位置、机械师的名字。这些东西在你脑子里放了很多天，像一块能咬的干粮。"},strip:{text:"拆了卖零件",outcome:"四十信用点，发动机卖了二十五，船壳卖了十五。机械师看着你把最后一块铁皮搬走，什么也没说。"}}},pub_bounty_after:{title:"猎人来道别",desc:"那个领了赏金的男人坐在吧台角，面前摆着两杯酒。他把其中一杯推向你。“我不干了。”他说，“这行当里，我今天杀的人，明天就会来杀我。”",choices:{drink:{text:"陪他喝一杯",req:"需 8 信用点",outcome:"你们喝到打烊。他说了很多话，你一句也没记住，只记得他最后说“你不像干这行的”。"},ask_client:{text:"问他是谁下的单",outcome:"他沉默了很久，说了一个名字。那个名字属于检疫处三号办公室。你后来再也没去过那一层。"},take_gun:{text:"抢他的枪",outcome:"你从背后下手，他没来得及反应。枪比你想的重。他躺在地上看着你，说：“我早该知道。”"}}},pub_rota_use:{title:"那张值班表现在能用了",desc:"你手里的排班表已经过期一半，但巡逻盲区不会变。今晚八点到九点二十，B 段围墙没有人。",choices:{tell_rachel:{text:"告诉瑞秋",outcome:"她当晚就送出去三个人。回来时鞋上全是泥，说：“你比我想的靠谱。”这是她第一次夸人。"},self_use:{text:"自己用这个空档",outcome:"你在那八十分钟里穿过了两道封锁线，看了一眼封锁线外是什么样子。外面什么都没有，只有更多的围墙。"},sell:{text:"卖给检疫处",outcome:"三十五信用点。他们问消息从哪来，你说“值班时听说的”。他们没有再问，但把你的名字记了下来。"}}},pub_list_rumor:{title:"名单是可以买的",desc:"酒馆里有人在传：撤离名单不是抽签的，是卖的。四百个位置，三百个已经内定，剩下的一百个在暗盘上叫价。",choices:{probe:{text:"花钱打听买家",req:"需 10 信用点",outcome:"十信用点换来一个名字和一间办公室的门牌号。你把它们记在一张酒单背面，字迹很轻。"},warn:{text:"告诉瑞秋，让她的人别等",outcome:"她听完只说了句“知道了”，当晚就把两个船员送上了货车。她信你，这在这个区很罕见。"},save:{text:"什么都不做，继续攒钱",outcome:"你把酒喝完，回去数了三遍存款。数字没变，但你觉得它变轻了。"}}},pub_last_smoke_variant:{title:"最后一次，她给你留了后门",desc:"瑞秋在打烊后留了一盏灯。“货舱十九号，我给你留着。”她把钥匙放在吧台上，“别谢我。你只要记得，那位置本来是我船员的。”",choices:{promise:{text:"答应她，会带一个人上来",outcome:"你握了握那把钥匙，什么也没说。她笑了，说“我就知道你会答应”。这可能是她第一次说错话。"},truth:{text:"告诉她你可能会自己走",outcome:"她点点头，把钥匙收回去，又推回来。“随你。”她说，“反正这地方也快没了。”"}}},dorm_rest:{title:"铁床上的两个小时",desc:"宿舍的窗户关不严，风从缝里灌进来。上铺的人在打呼，走廊尽头有人在低声念什么。你把外套盖在脸上，试图睡一会儿。",choices:{sleep:{text:"睡吧",outcome:"你睡了大概两个小时，梦见自己在盖章，一直盖，盖到手指磨破。"}}},dorm_radio:{title:"短波电台",desc:"执勤宿舍有一台老式短波机。你戴上耳机慢慢转着旋钮，在无数杂音之间突然抓到一个清晰的女声：“……第三批撤离名单已变更，潜艇将于……”信号断了。",choices:{tune_in:{text:"继续调，把这段听完",outcome:"你花了四十分钟，终于把时间拼了出来：潜艇提前了整整一天。这个信息，明晚可能救你一命。"},switch_off:{text:"关掉",outcome:"你摘下耳机，世界重新变得安静而模糊。有些事情，不知道反而睡得着。"}}},dorm_nightmare:{title:"又是那个梦",desc:"你梦见自己坐在窗口后面，外面排队的人一个个走进来，每个人都长着同一张脸。你不停地盖章，纸张堆到天花板。你想停下，但手不听你的。",choices:{wake:{text:"惊醒，坐起来",outcome:"你猛地坐起，后背全是汗。上铺的人翻了个身。凌晨四点，窗外在下雨。"},write:{text:"摸黑把梦记在日志背面",outcome:"你写了三页。写完的时候心跳慢了下来。原来把它写出来，它就没那么大了。"},drink:{text:"喝掉床头那半瓶劣质酒",outcome:"你灌了半瓶，脑子里的声音终于小了下去。第二天早上，你的手抖得盖不准章。"}}},dorm_journal:{title:"值班日志的空白页",desc:"你在日志的空白页上写字。写着写着，发现自己已经记不清第一天那件事的细节了。你只记得有个女人在雨里，还有一双掉在水洼里的鞋。",choices:{write:{text:"继续写下去",outcome:"你写了很久，纸被笔尖划破了好几处。合上本子的时候，你觉得自己好像轻了一点。"}}},dorm_neighbor:{title:"隔壁的哭声",desc:"隔壁宿舍传来压着嗓子的哭声，是那个刚满十九岁的实习生。他今天第一次在闸门值班。你没问他看见了什么，你能猜到。",choices:{check:{text:"敲他的门，坐一会儿",req:"需 5 信用点",outcome:"你带着两罐啤酒过去，一句话都没问。他喝到第二罐才开口，说了很久。天亮的时候他睡着了。"},ignore:{text:"翻个身，装作没听见",outcome:"你翻了个身，用枕头捂住耳朵。哭声持续到凌晨两点，然后停了。你也一直没睡着。"}}},dorm_mirror:{title:"盥洗室的镜子",desc:"水龙头滴着水。你抬头，看见镜子里的自己——眼窝陷进去了，嘴角向下，眼神像在看一个陌生人。你忽然想不起来，五天前那张脸是什么样子。",choices:{confront:{text:"盯着镜子，把话说清楚",outcome:"你对着镜子说：我知道我做了什么，我会带着它活下去。说完这句，镜子里那个人终于有点像你自己了。"},turn_away:{text:"低头洗手，不看",outcome:"你洗完手就走了。回去的路上，你一直避免经过任何能反光的东西。"}}},dorm_letter:{title:"一封家书",desc:"床垫下面压着一封没拆的信，是两个月前寄来的。信封上是你妹妹的字，邮戳上写着“已检疫”。你一直没有勇气拆开。",choices:{read:{text:"拆开读",outcome:"信里说家里都好，院子里的树今年结果了，问你什么时候回来。你读完，把它折好放回信封，然后哭了一场。"},burn:{text:"烧掉，不看",outcome:"你点着了它，看它在地板上卷成一团灰。你不确定自己是在保护自己，还是在放弃什么。"}}},gate_mother_child:{title:"发烧的女孩与过期通行证",desc:"夜雨倾盆。一个浑身湿透的女人抱着昏迷的孩子跪在窗口前，把一张通行证贴在玻璃上——日期是昨天，印章的红色被雨水泡开了。“求求你，她只是肺炎，不是灰烬症。让我们过去，就这一次。”她身后的监控探头正闪着红光。",choices:{let_through:{text:"违规放行：在监控死角按下绿色通行章",req:"需 10 信用点抵罚款",outcome:"你把通行证塞进读卡器，用袖子挡住镜头，按下了绿章。女人没有说谢谢，只是用额头抵了一下玻璃，然后消失在雨里。月底的绩效表上会多一行红字。"},report:{text:"冷血举报：拉响警报，领取举报赏金",outcome:"警报撕开夜空，防暴队把她们拖走了。孩子的一只鞋掉在水洼里。系统自动打给你 25 信用点，备注栏写着“协助检疫”。"},refuse:{text:"公事公办：退回证件，拉下百叶窗",outcome:"“证件过期，下一个。”你拉下防弹玻璃的百叶窗，哭声被隔在外面，变得很远。今日基础执勤薪水已入账。"}}},gate_mother_revenge:{title:"暗巷里的复仇枪声",desc:"你刚交完班走出执勤亭，一根冰冷的管口顶住了你的后脑。“你还记得三天前你举报的那对母女吗？隔离营昨晚清空了。”男人的声音在发抖，比枪更让你害怕。",choices:{pay:{text:"把身上所有的钱撒在地上换命",req:"需 35 信用点",outcome:"你把钞票全撒进积水里，趁他弯腰去捡的一瞬间滚进排水沟。枪托砸在你肩上，但你活下来了。"},fight:{text:"拼死夺枪",outcome:"枪响了，子弹擦过你的肋骨。你把他压在身下时才看清，他比你还瘦。他没有再挣扎，只是看着你的眼睛。"},call_backup:{text:"按下对讲机，呼叫防暴队",outcome:"三分钟后防暴队到了。他们处理得很干净，你不需要知道细节。只是从那以后，你听见有人在夜里敲墙。"}}},gate_pharma_convoy:{title:"没有牌照的装甲车队",desc:"深夜，三辆黑色装甲车停在闸门前。车窗降下，一个西装男人递出一张黑卡：“别问箱子里是什么。抬杆，这钱够你买半张船票。”后车厢里传出轻微的、规律性的撞击声。",choices:{take_card:{text:"收下黑卡，闭眼抬杆",outcome:"车队呼啸而过，空气里留下一股福尔马林的味道。你数了三遍卡里的余额，手一直在抖。"},inspect:{text:"坚持开箱例行检查",req:"需理智 ≥ 50",outcome:"箱子里是违禁的血清样本。男人见你不好惹，丢下一叠封口费掉头走了。你记下了车牌。"},turn_away:{text:"什么都不做，看着他们离开",outcome:"你退回亭子里，假装没看见。车队等了两分钟，自己绕道走了。今晚的日志你只写了“无异常”。"}}},gate_pharma_audit:{title:"监察处的传唤",desc:"一张盖着红章的纸贴在亭子玻璃上：你被列入“例行审计”名单。审讯室的白炽灯直射你的眼睛，桌子对面的人翻着三个月前的通行记录，慢慢念出那三辆装甲车的车牌号。",choices:{confess:{text:"如实交代，主动退还赃款",outcome:"你签了字，退了钱，被记大过一次。走出审讯室的时候天刚好亮，你居然觉得轻松。"},bribe_auditor:{text:"把剩下的钱推过桌面",req:"需 25 信用点",outcome:"他数都没数，直接把钱扫进抽屉。“这份记录我会‘归档’。”他说。归档的意思你懂。"},deny:{text:"一口咬定什么都没发生",outcome:"他们找不到证据，但把你调去了最冷的夜班岗。你的名字被画了一个圈，那意味着永远有人在看着你。"}}},gate_inspector:{title:"上级的突击巡查",desc:"督查官没有提前通知就出现在岗亭。他戴着白手套翻你的登记本，一页一页，很慢。“这个章盖得不太规范啊。”他说，眼睛却看着你抽屉的方向。",choices:{bribe:{text:"往他口袋里塞点东西",req:"需 20 信用点",outcome:"他把钱折成两半塞进内袋，然后在你的本子上写下“执勤规范，记录完整”。"},honest:{text:"照实汇报所有情况",outcome:"他听完沉默了很久，最后在你的档案里加了一句“可用”。这句评语值五块奖金。"},push_back:{text:"顶回去：这些章都是按你的命令盖的",outcome:"他的脸涨红了，但没再说什么。督查官走的时候把门摔得很响。你赢了一局，也记了一笔。"}}},gate_deserter:{title:"逃兵和他的家人",desc:"一个还穿着制服的年轻人抱着婴儿，身边跟着他妻子。他把配枪放在窗台上，枪口朝向自己：“我把枪交了。我们只是想去南边，那里还有没封锁的港口。”系统显示他是三小时前从东区防线上失踪的。",choices:{let_pass:{text:"收下枪，放他们过去",req:"需 15 信用点",outcome:"你收了枪，注销了通行记录，还塞给他们一点钱。年轻人的妻子回头看了你一眼，那眼神你很久都忘不掉。"},report:{text:"按条例上报",outcome:"三十信用点赏金到账。报告系统里他被标记为“逃兵·已处理”。处理这两个字在屏幕上很扎眼。"},take_gear:{text:"敲他一笔，再放行",outcome:"你要下了他的防水表和防毒面具，值二十块。他没反抗，只是把婴儿抱得更紧了。"}}},gate_body_cart:{title:"运尸车的数目不对",desc:"清运车每晚来两趟。今晚司机递过来的单子上写着 14 具，车厢里却明显塞了不止十四个裹尸袋。“多出来的是黑货，”司机压低声音，“你要是不看，这里面有你一份。”",choices:{look_inside:{text:"开箱清点",outcome:"多出来的五个袋子里装的是走私烟和抗生素。你抽走了一部分“保管费”，剩下的签字放行。"},wave_through:{text:"签字，不看",outcome:"你在单子上签了字，司机塞给你一卷钞票。今晚你没有做任何决定，这或许也是一种决定。"}}},gate_riot:{title:"闸门外的两千人",desc:"人群从贫民区一路涌到闸门外，铁门被撞得嗡嗡响。上级的指令只有四个字：维持秩序。你手里有催泪弹，腰上有枪，闸门外有孩子、老人，还有昨天给你送过热水的大婶。",choices:{fire_warning:{text:"鸣枪示警，发射催泪弹",outcome:"瓦斯在雨里散开，人群尖叫着后退，踩踏中有十几个人没能站起来。你被记了功，也再没去过那家卖热水的铺子。"},open_gate:{text:"违反命令，打开闸门",outcome:"铁门升起时人群安静了一瞬，然后像潮水一样涌进来。你被停职、扣光津贴，但你收到了一整袋热馒头。"},call_backup:{text:"呼叫防暴队，自己退回亭子里",outcome:"防暴队“处理”了这场骚乱。你在亭子里听着，隔着两层玻璃。事后你拿到了十五块津贴。"}}},gate_children:{title:"贴着闸门的一群孩子",desc:"七八个孩子挤在闸门上，最大的看起来十二岁，最小的还抱在怀里。他们没有通行证，是被人从隔离区偷运出来的。“叔叔，我们不想被烧掉。”最大的那个说。",choices:{register:{text:"逐个登记，走正规流程",outcome:"你把他们登记进了收容队列，系统给了你十二块登记津贴。你知道那个队列的另一头是什么。"},hide:{text:"把他们藏进执勤亭后面的仓库",req:"需 15 信用点",outcome:"你花了点钱买通巡逻，把他们塞进仓库。今晚亭子里很安静，只有仓库偶尔传来一点动静。"},send_back:{text:"通知隔离区来领人",outcome:"隔离区的车十分钟后到了。你没有出去看。那天之后，你听见孩子的笑声会下意识地屏住呼吸。"}}},gate_new_order:{title:"封城令",desc:"加密频道传来新命令：明日零时起，Sector-07 只出不进，所有未登记人员就地隔离。命令最后一行写着：本令不得向非执勤人员透露。你知道瑞秋的走私舱里还有二十个人在等船。",choices:{obey:{text:"执行命令，闭嘴",outcome:"你在命令栏点了“已阅”。明天开始，闸门只朝一个方向开。"},warn_rachel:{text:"把消息透露给瑞秋",outcome:"你趁换岗的十分钟溜进酒馆。瑞秋听完只说了两个字：“多谢。”她会记住这件事。"},ignore:{text:"当作没收到，什么都不做",outcome:"你没有点“已阅”，也没有告诉任何人。命令还是在零点生效了。你花了一点钱，替几个熟人办了假登记。"}}},gate_bribe_small:{title:"塞进窗口的信封",desc:"一个商人模样的男人把信封推进窗口：“一点心意，我这批货有点急。”信封的厚度大概值十二块。后面还有十几个人在排队。",choices:{take:{text:"收下，加快办理",outcome:"信封进了你的内袋，他的车在三十秒内通过了闸门。后面的人还在等。"},refuse:{text:"按流程办",outcome:"你把信封推了回去。他愣了一下，然后规规矩矩地排到队尾。三块钱的加班费是你今晚唯一的额外收入。"}}},gate_quiet_night:{title:"平淡的一夜",desc:"雨停了，闸门外只有几个零星的登记。你换了一壶热水，把哨位上的台灯调暗了一档。远处传来潜艇码头的汽笛，每晚三次，从不延误。",choices:{stamp:{text:"继续盖章，等天亮",outcome:"一整夜过去了，只有四张通行证。你在日志最后一行写下“未发现异常”，然后趴在桌上睡了二十分钟。"}}},market_forger:{title:"假证贩子",desc:"集市深处，一个没有左手的男人在卖通行证。“六十块，真的那种。潜艇的货舱不看脸，只看章。”他把一张纸对着光，纸的纤维走向和真证一模一样。",choices:{buy_papers:{text:"买一张",req:"需 35 信用点",outcome:"纸是真的，章也是真的——从一个死人身上剥下来的。他把纸折好递给你：“记住，别在码头回头看。”"},refuse:{text:"摇头走开",outcome:"你走开了。他在背后喊：“明天就涨价了！”你没有回头。"}}},market_organs:{title:"身体也是货币",desc:"一个穿白大褂的人在临时搭的棚子里做“回收”。他打量你的眼神像在称重：“一个肾，五十五。手术很干净，两小时，你能自己走回去。”",choices:{sell:{text:"卖掉",outcome:"你拿到五十五块，走路的时候得扶着墙。止痛药不太管用，钱很管用。"},walk:{text:"离开",outcome:"你走出棚子，深吸了一口气。肺还在，肾也还在。"}}},market_pawn_gun:{title:"典当配枪",desc:"当铺老板用两根手指捏起你的配枪，像捏一件脏东西：“三十五。这玩意儿现在没人要了，枪又不能吃。”",choices:{pawn:{text:"当掉",outcome:"你把枪换了三十五块和一张当票。走出门的那一刻，你才意识到自己在这座城里再没有任何可以依靠的东西。"},keep:{text:"收回去",outcome:"你把枪别回腰上。老板耸耸肩：“随你，反正明天更不值钱。”"}}},market_thief:{title:"偷罐头的小孩",desc:"一个不到十岁的孩子被抓着后领提在半空，手里还死死攥着一罐午餐肉。摊主在喊：“打断他的手！”孩子的脚在空中乱蹬，没有哭。",choices:{catch:{text:"按摊主说的办",outcome:"你抓住了他的手腕，摊主踢了他两脚，然后扔给你十块钱“辛苦费”。孩子跑掉时罐头掉在地上，滚进了下水道。"},buy_food:{text:"把罐头买下来，放他走",req:"需 15 信用点",outcome:"你付了钱，还多买了一罐塞给他。他跑出去十几米，回头看了你一眼，然后消失在人群里。"},let_go:{text:"让他跑",outcome:"你松开手，孩子像条鱼一样钻进人群。摊主骂了你一句，你没理他。"}}},market_fake_medicine:{title:"灰烬症特效药",desc:"一个摊子上摆满花花绿绿的瓶子：“专治灰烬症，十五一瓶，最后一个疗程了。”瓶底的批号是手写上去的，墨还没干。",choices:{buy:{text:"买一瓶",outcome:"喝下去之后，你的胃疼了一整夜。批号上那个厂，三年前就烧掉了。"},refuse:{text:"不买",outcome:"你把瓶子放下，摊主立刻转向了下一个客人。"}}},market_dice:{title:"巷子里的骰子",desc:"三个男人蹲在墙根下赌骰子，看到你走过来，其中一个把骰盅推到你面前。骰子的重心不太对，你看得出来，但他们不介意你看得出来。",choices:{roll:{text:"押二十块",req:"需 20 信用点",outcome:"骰盅在墙根下被揭开，四个人都盯着那三颗骰子。",win:"全红。三个人一起骂了句什么，把三十八块推给你。你收钱的时候手很稳。",lose:"全黑。你把二十块放上去，听见其中一个人笑了一声。那笑声跟了你一整条街。"},pass:{text:"笑着摆手",outcome:"你摆摆手走了。身后传来骰子落地的声音和一阵骂声。"}}},market_rumor:{title:"集市上的消息",desc:"肉摊老板一边剁骨头一边跟你聊天：“听说了吗？潜艇改了班次，提前一天走。上头不想让太多人知道。”他说这话的时候没有抬头。",choices:{listen:{text:"买点肉，听他说完",outcome:"你花了五块钱买了半斤不知道是什么的肉。消息比肉值钱：潜艇真的提前了。"}}},market_ration:{title:"倒卖配给券",desc:"配给站后门，一个穿制服的人在收券：“十八块一张，现金。”你知道这些券是从哪来的——从那些没能活到今天的人手里。",choices:{sell:{text:"卖掉自己这周的券",outcome:"你换了十八块钱。接下来三天，你靠喝水和抽烟撑着。"},share:{text:"把券给排队的老太太",outcome:"你把券塞给一个抱着空锅的老太太。她追了你半条街要说谢谢，你走得更快了。"}}},medbay_routine:{title:"隔离区医疗站",desc:"消毒水的味道刺得人眼睛发酸。值班医生连头都没抬：“抗感染血清十五，神经镇定剂十五。先付钱，后打针。”",choices:{serum:{text:"打一针抗感染血清",req:"需 15 信用点",outcome:"冰凉的药液推进血管，你的体力在几分钟内回到了身上。"},sedative:{text:"打一针神经镇定剂",req:"需 15 信用点",outcome:"耳边的嗡嗡声慢慢退了。心脏有点闷，但世界终于安静了。"},leave:{text:"在走廊长椅上坐十分钟",outcome:"你在走廊尽头坐了十分钟，什么也没想，也没有看那些床。起身的时候，手不抖了。"}}},medbay_triage:{title:"只能救一个",desc:"一场小规模踩踏之后，医疗站只剩一剂血浆。床上有两个伤员：一个是七岁的女孩，一个是区议员的外甥——后者还清醒着，已经在打电话了。医生看着你：“你决定。”",choices:{save_child:{text:"给那个女孩",req:"需 20 信用点",outcome:"你自掏腰包补上了血库的缺口，女孩活了下来。议员办公室第二天打来电话，什么都没说就挂了。"},save_officer:{text:"给议员的外甥",outcome:"议员办公室送来二十块“感谢费”，并承诺“记住你”。女孩在凌晨三点被推走了，你没有跟出去。"},by_rule:{text:"按规程：先到先治",outcome:"按登记时间排序，女孩先到。你把这个决定推给了制度，制度给了你五块钱加班费。"}}},medbay_theft:{title:"被偷的药品",desc:"药柜少了一整盒止痛剂。监控拍到了值夜班的护工，一个单亲父亲。他站在你面前，手一直在抖：“我女儿在发烧……我不是卖，真的不是卖。”",choices:{report:{text:"上报，按盗窃处理",outcome:"他被带走了，你拿到十块钱举报奖励。药盒在证物袋里，你一直没敢看。"},cover:{text:"替他兜下来，自己补钱",req:"需 10 信用点",outcome:"你用自己的钱补了账，跟医生说药是过期销毁了。他没说谢谢，但从那天起每次都给你留一支最好的针剂。"},steal:{text:"自己也拿一份走",outcome:"你把剩下的一半也塞进了口袋。第二天，止痛剂的配给量被砍掉了三成。"}}},medbay_doctor:{title:"医生自己病了",desc:"值班医生的手背上出现了第一块灰斑。他自己也看见了，把袖子拉下来，继续写病历。“别告诉别人，”他说，“这里只有我一个能缝合伤口的人。”",choices:{give_meds:{text:"把血清留给他",req:"需 25 信用点",outcome:"你把血清的钱付了，还多买了一支。他的灰斑在第三天退了下去。后来他救过你一次。"},walk_away:{text:"当作没看见",outcome:"你什么都没做。三天后，医疗站门口贴上了新的值班表，上面没有他的名字。"},report_doctor:{text:"上报，申请隔离",outcome:"他被带走那天，医疗站关闭了六个小时。你拿到十五块“主动上报”奖金，和一张写着“尽职”的评语。"}}},medbay_painkiller:{title:"黑市止痛剂",desc:"医生从抽屉里摸出一支没有标签的针管：“这个不上账，五块。能让你四个小时感觉不到任何东西——包括良心。”",choices:{take:{text:"打一针",outcome:"四个小时里，你像个正常人一样呼吸、说话、盖章。药效过去的时候，所有东西一起回来了。"},refuse:{text:"算了",outcome:"你把针管推回去。走的时候，你觉得自己的手还算稳。"}}},medbay_last_patient:{title:"最后一个病人",desc:"撤离前夜，一个老人被人搀进来。他的通行证是真的，但名字在昨晚的封锁名单上。医生已经跟着第一批撤离队走了，站里只剩你，和一柜子锁着的药。",choices:{treat:{text:"撬开药柜，给他治疗",req:"需 30 信用点",outcome:"你撬了锁，用掉了大半库存。老人天亮前退了烧。这件事你没有登记。"},refuse:{text:"关灯，锁门",outcome:"你关了灯，在门外听见他咳嗽了一整夜。早上门开的时候，他已经不咳了。"}}},pub_rachel_deal:{title:"走私头目瑞秋",desc:"酒馆老板娘瑞秋在吧台后面擦一只已经裂了口的杯子。她把一杯浑浊的酒推到你面前：“潜艇的舱位不是钱能买到的，长官。想让我把你塞进去，你得先证明自己靠得住。”",choices:{buy_intel:{text:"买她的情报，陪她喝一杯",req:"需 15 信用点",outcome:"你付了钱，她低声报出一个船期和一句暗号。“记住，别在闸门那边提起我的名字。”"},forge:{text:"帮她伪造一批通关文书",outcome:"你用执勤亭的印章盖了二十份文书，赚了一笔外快。代价是你一整晚都在发抖。"},listen:{text:"什么都不买，就在吧台坐着",outcome:"你点了一杯最便宜的，听了半宿别人的故事。离开的时候，脑子难得地安静。"}}},pub_mechanic_gift:{title:"机械师的谢礼",desc:"角落里一个满手油污的男人压着帽檐向你招手：“长官，我是那天那对母女的丈夫。她们到安全区了，孩子退烧了。这是我从潜艇维修厂顺出来的东西。”他推过来一个牛皮纸袋。",choices:{accept:{text:"收下这份谢礼",outcome:"纸袋里是三十块钱和一张维修厂的内部通行证。瑞秋在旁边挑了下眉：“没想到你这铁面警卫还挺有人味。”"},refuse:{text:"推回去，让他留给家人",outcome:"他把纸袋收回去，眼睛红了。瑞秋给你倒了一杯不收费的酒。“你这个人，”她说，“活不长的。”"}}},pub_rachel_test:{title:"瑞秋的考验",desc:"瑞秋把一个上了锁的铁盒推到你面前：“明天早上会有人来问你有没有见过这个盒子。你要是说没见过，我们就有的谈了。这里面是二十个人的命。”",choices:{prove:{text:"收下盒子，替她扛下来",req:"需 20 信用点",outcome:"你把盒子藏进执勤亭的暗格，还花钱打点了可能来问话的人。瑞秋看你的眼神变了。"},refuse:{text:"把盒子推回去",outcome:"“我不掺和这种事。”你把盒子推回去。她点点头，没有生气，只是把你的酒收走了。"}}},pub_ticket_cash:{title:"现金买舱位",desc:"瑞秋把一个信封拍在吧台上：“今晚有人退了一个位子。九十块，现金，不还价。明天这个时候，就不是这个价了。”",choices:{buy_now:{text:"付款，定下这个位子",outcome:"你把九十块推过去，她数都没数就收进围裙。她给了你一个手写的号码：货舱十九号。"},haggle:{text:"压价，暗示你知道举报电话",outcome:"她盯着你看了很久，最后收了七十。“行，你省了二十块。但这个位子没有通风口。”"}}},pub_bounty:{title:"有人悬赏你的脑袋",desc:"你刚坐下，酒馆就安静了。三个人堵住门口，为首的那个把一张纸拍在桌上，上面是你的工号和一张模糊的照片。“有人出了四十块，买你今晚别回家。”",choices:{pay_off:{text:"花钱买平安",req:"需 40 信用点",outcome:"你把钱推过去。他收了钱，撕了那张纸。“下次价格会涨。”他走的时候说。"},fight:{text:"抄起酒瓶动手",outcome:"你打断了其中一个人的鼻梁，自己被按在地上揍了一顿。最后是瑞秋用撬棍把他们赶出去的。"},run:{text:"从后门跑",outcome:"你翻过后巷的围墙，摔进垃圾堆，扭伤了脚踝。第二天你没去上班，也没有人问。"}}},pub_rachel_farewell:{title:"最后一支烟",desc:"潜艇明晚离港。瑞秋站在酒馆门口抽烟，看街上最后一批人拖着行李往码头走。“你还有一晚上，”她把烟递给你，“想清楚你要什么。”",choices:{stay:{text:"陪她站到天亮",outcome:"你们什么都没做，只是一根接一根地抽烟，看天一点点亮起来。她最后说：“要是你走不了，我这后面还有个位置。”"},ask_jump:{text:"问她能不能把你塞进货舱",req:"需瑞秋好感 ≥ 20",outcome:"她看了你一眼，把烟头按在门框上：“别问。明晚，后门，别带多余的东西。”"}}},pub_drunk:{title:"醉汉的末日笑话",desc:"一个喝多的码头工人趴在吧台上，反复讲同一个笑话：为什么灰烬症不传染给富人？因为他们早就买好了船票。他讲一次，周围的酒客笑一次，笑到后面像是在哭。",choices:{listen:{text:"听完，跟着笑一声",outcome:"你笑了一下，忽然发现自己已经很久没有笑过了。这一晚的酒钱花了三块。"}}},pub_bet:{title:"吧台边的赌局",desc:"两个矿工在赌骰子，看到你过来，把骰盅推到你面前：“长官也来一手？十五块起。”骰盅内壁有点发亮，你知道那是什么意思，但今晚你不想在乎。",choices:{gamble:{text:"押十五块",req:"需 15 信用点",outcome:"骰盅揭开的瞬间，周围一片哗然。",win:"三点全红。矿工骂了一句脏话，把四十五块推到你面前。你听见自己笑出了声，那声音有点陌生。",lose:"三点全黑。你盯着桌面看了三秒，然后掏出十五块。矿工拍拍你的肩：“长官，明天还来吗？”"},watch:{text:"看着，不下注",outcome:"你站在旁边看了半个钟头，最后那两个人都输光了。你什么都没赢，也没输。"}}},pub_song:{title:"酒馆里的歌",desc:"有人用口琴吹起一支很老的调子。整个酒馆慢慢安静下来，连瑞秋都停了手上的活。你忽然想起这首歌在你小时候的收音机里放过。",choices:{stay:{text:"坐下听完",outcome:"曲子结束的时候没有人鼓掌，大家都低着头。你付了五块钱，觉得值。"}}}},s={ending_together:{title:"四个人的舱位",desc:"潜艇只有两个位置，最后上去了四个人。你说不清是怎么做到的——也许是有人把证件塞给了别人，也许是瑞秋在最后一刻撕了货舱的封条。你们挤在四十公分高的夹层里，谁也没说话。到岸时天在下雨，和离开时一样。"},ending_gateopen:{title:"开门的人",desc:"你按下绿色按钮，然后关掉了监控。六万人在八个小时里穿过 7 号闸门。检疫处的档案里，这一页被标注为“设备故障”。没有人追究，因为追究的人也在队伍里。"},ending_broadcast:{title:"四百个名字",desc:"那天晚上，全城的短波都在念同一份名单。第三天宪兵开始砸收音机，第四天有人把名单抄在墙上。潜艇离港时，港外站满了人，一个字都没喊。"},ending_cure:{title:"零下十八度的答案",desc:"配方被念了四个小时，四个隔离营开始自己配药。你没能上那班潜艇，但灰烬症的死亡率在两周内从六成掉到两成。后来有人在墙上写：陈医生的方子。"},ending_identity:{title:"借来的名字",desc:"你用一个死人的名字上了船。护照上的女人二十九岁，照片里在笑。整整两天，没有一个人叫你的真名。你在新的城市找了份工作，用的是她的生日。"},ending_boat:{title:"两点钟的潮水",desc:"机械师的拖船在两点钟离岸，八个人，一台随时会熄火的发动机。你们用手划了四个小时。天快亮时有人开始笑，然后所有人都在笑，包括那个一直在吐的孩子。"},ending_soldlist:{title:"四百个空位",desc:"名单卖了九十信用点，你用它买了船票。潜艇离港时，货舱里有三百六十个空位。你坐在其中一个旁边，听见邻座问：“这些人呢？”你说：“他们没赶上。”"},ending_golden:{title:"黄金船票持有者",desc:"最后一天深夜，你掏空全部积蓄，买下了最后一班撤离潜艇的头等舱。舱门关闭时，你透过舷窗看见闸门那边还有人在挥手。你没有回头。"},ending_smuggler:{title:"暗夜走私客",desc:"你没攒够那张天价船票，但瑞秋把货舱的暗格打开了一条缝。“别出声，”她说，“也别忘了欠我一条命。”潜艇下潜时，你听见外面有人在敲舱壁。"},ending_cutrate:{title:"没有通风口的位子",desc:"你手里那张假证的印章是从一个死人身上剥下来的。货舱十九号没有通风口，你蜷在四十公分高的夹层里撑了十一个小时。潜艇靠岸时你几乎是被拖出去的——但你活着。"},ending_lighthouse:{title:"第 7 区的灯塔",desc:"你没有上潜艇。最后一天清晨，闸门外聚集了上千人，他们举着你的名字，把闸门从外面推开了。你没有成为撤离者，你成了留下来的人里第一个开口的人。"},ending_loyalist:{title:"被晋升的守备官",desc:"你的报告写得漂亮，处置果断，系统给了你一个更好的岗位——去管理更大的隔离区。晋升通知上印着你的工号，下面一行小字：本岗位不得申请撤离。"},ending_forgotten:{title:"被遗忘的守卫",desc:"潜艇的汽笛在港口响起，一遍，两遍，三遍。你既没攒够船票，也没打通任何关系。大铁门缓缓落下时，你还在岗亭里，手里握着一枚没有盖下去的章。"},ending_dead:{title:"7 号闸门的殉职者",desc:"你的生命体征在执勤岗位上归零。清理小队第二天早上把你抬走，登记表上写着“因公”，编号后面跟着一个干净的勾。"},ending_mad:{title:"狂乱的守门人",desc:"长期的道德折磨终于把你压垮。你锁死闸门，吞掉钥匙，在广播里反复念着同一份名单。破门的人冲进来时，你正在给自己盖章。"},ending_starved:{title:"饥饿的幽灵",desc:"你没有死在闸门边，也没有死在枪口下。你死在宿舍那张冰冷的铁床上，胃里什么都没有。第二天你的岗位被另一个人填上了，只用了四个小时。"}},a={meta:e,ui:t,npcs:o,locations:c,events:i,endings:s};export{a as default,s as endings,i as events,c as locations,e as meta,o as npcs,t as ui};
